import { Controller, Get, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 미리보기 가능 확장자 (HWP·Word·Excel·PPT)
const PREVIEW_EXTENSIONS = ['hwp', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'];

// 가정: 임직원 권한으로 접근한 사용자는 다운로드를 허용한다 (세부 사용 권한은 공통 모듈이 맡는다)
const DOWNLOAD_ALLOWED = true;

const MAX_SIZE = 200;
const DEFAULT_SIZE = 20;

function isDigits(value: unknown): boolean {
  return typeof value === 'string' && /^[0-9]{1,18}$/.test(value);
}

function isPreviewable(extension: unknown): boolean {
  if (typeof extension !== 'string') {
    return false;
  }
  const normalized = extension.replace(/^\./, '').toLowerCase();
  return PREVIEW_EXTENSIONS.includes(normalized);
}

@Controller('api/v1')
export class FnSfr03105Controller {
  @Get('/attachments')
  async listAttachments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const targetType = query['targetType'];
    const targetId = query['targetId'] === undefined || query['targetId'] === null ? '' : String(query['targetId']);
    if (typeof targetType !== 'string' || targetType.trim() === '' || targetType.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '업무 대상 유형을 확인해 주세요.');
    }
    if (!isDigits(targetId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '업무 대상 ID는 숫자로 입력해 주세요.');
    }
    const pageText = query['page'] === undefined || query['page'] === null || query['page'] === '' ? '0' : String(query['page']);
    const sizeText = query['size'] === undefined || query['size'] === null || query['size'] === '' ? String(DEFAULT_SIZE) : String(query['size']);
    if (!isDigits(pageText) || !isDigits(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 숫자로 입력해 주세요.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), MAX_SIZE);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT attachment_id AS "attachmentId", file_name AS "fileName", file_extension AS "fileExtension", file_size AS "fileSize" ' +
          'FROM attachment ' +
          'WHERE target_type = :targetType AND target_id = CAST(:targetId AS bigint) ' +
          'ORDER BY attachment_id ' +
          'LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { targetType, targetId, size, offset: page * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM attachment ' +
          'WHERE target_type = :targetType AND target_id = CAST(:targetId AS bigint)',
        { targetType, targetId },
      );
      const items = rows.map((row: any) => ({
        attachmentId: Number(row.attachmentId),
        fileName: row.fileName,
        fileExtension: row.fileExtension,
        fileSize: row.fileSize === null || row.fileSize === undefined ? null : Number(row.fileSize),
        downloadAllowed: DOWNLOAD_ALLOWED,
        previewAvailable: isPreviewable(row.fileExtension),
      }));
      return { items, page, size, total: Number(counts[0]?.total ?? 0) };
    });
  }

  @Get('/attachments/:attachmentId/download')
  async downloadAttachment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const attachmentId = req.params['attachmentId'];
    if (!isDigits(attachmentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '첨부파일 ID는 숫자여야 합니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT attachment_id AS "attachmentId", ecm_ref AS "ecmRef" ' +
          'FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)',
        { attachmentId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTACHMENT_NOT_FOUND', '첨부파일을 찾을 수 없습니다.');
      }
      if (!DOWNLOAD_ALLOWED) {
        throw new ApiError(422, 'DOWNLOAD_NOT_ALLOWED', '다운로드 권한이 없어 미리보기만 제공합니다.');
      }
      const ecmRef = rows[0].ecmRef;
      if (ecmRef === null || ecmRef === undefined || ecmRef === '') {
        throw new ApiError(502, 'ECM_LINK_FAILED', 'ECM 연계에 실패했습니다. 잠시 후 다시 시도해 주세요.');
      }
      // 가정: ECM 조회 모듈이 없어 ECM 저장 참조(ecm_ref)를 file로 돌려준다
      return { file: String(ecmRef) };
    });
  }
}

