import { useState } from 'react';
import { Band, Badge, DataTable, ErrorText, Field, Filters, Drawer, Num, Pager, Pairs, TextInput, NumberInput, call, useData } from '../kit';
import type { PageProps, Page, Row } from '../kit';

const PAGE_SIZE = 20;

interface Applied {
  targetType: string;
  targetId: number | string;
}

interface View {
  title: string;
  items: [string, string][];
}

export default function FnSfr03105Page({ role, notify }: PageProps) {
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState<number | string>('');
  const [applied, setApplied] = useState<Applied | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [message, setMessage] = useState('');
  const [view, setView] = useState<View | null>(null);

  const { data, error, loading } = useData<Page | undefined>(async () => {
    if (!applied) {
      return undefined;
    }
    return call<Page>('GET', '/attachments', role, undefined, {
      targetType: applied.targetType,
      targetId: applied.targetId,
      page: pageNo,
      size: PAGE_SIZE,
    });
  }, [applied, pageNo, role]);

  const search = () => {
    if (targetType.trim() === '' || targetId === '') {
      setMessage('업무 대상 유형과 업무 대상 ID를 입력해 주세요.');
      return;
    }
    setMessage('');
    setPageNo(0);
    setApplied({ targetType: targetType.trim(), targetId });
  };

  const reset = () => {
    setTargetType('');
    setTargetId('');
    setMessage('');
    setPageNo(0);
    setApplied(null);
  };

  const fail = (e: unknown) => {
    notify(e instanceof Error ? e.message : '처리하지 못했습니다.');
  };

  const openPreview = async (row: Row) => {
    try {
      const result = await call<Row>('GET', '/attachments/' + String(row.attachmentId) + '/preview', role);
      setView({
        title: '미리보기',
        items: [
          ['파일명', String(result.fileName ?? '')],
          ['확장자', String(result.fileExtension ?? '')],
          ['변환된 미리보기 문서 내용', String(result.previewContent ?? '')],
        ],
      });
    } catch (e) {
      fail(e);
    }
  };

  const openDownload = async (row: Row) => {
    try {
      const result = await call<Row>('GET', '/attachments/' + String(row.attachmentId) + '/download', role);
      setView({
        title: '다운로드',
        items: [
          ['파일명', String(row.fileName ?? '')],
          ['ECM에서 가져온 파일 내용', String(result.file ?? '')],
        ],
      });
      notify('첨부파일을 가져왔습니다.');
    } catch (e) {
      fail(e);
    }
  };

  const rows = data ? data.items : [];

  return (
    <div>
      <h1>첨부파일 관리</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label="업무 대상 유형" required>
          <TextInput value={targetType} onChange={setTargetType} placeholder="예: APPROVAL_DOCUMENT" />
        </Field>
        <Field label="업무 대상 ID" required>
          <NumberInput value={targetId} onChange={setTargetId} />
        </Field>
      </Filters>
      {message !== '' && <ErrorText text={message} />}
      {error !== '' && <ErrorText text={error} />}
      {!applied && <p>업무 대상 유형과 ID를 입력하고 조회하면 문서의 첨부파일을 볼 수 있습니다.</p>}
      {applied && (
        <div>
          <Band total={data ? data.total : 0} />
          <DataTable
            columns={[
              { key: 'fileName', label: '파일명' },
              { key: 'fileExtension', label: '확장자' },
              { key: 'fileSize', label: '파일 크기(바이트)', render: (row) => <Num value={row.fileSize} /> },
              {
                key: 'downloadAllowed',
                label: '다운로드 허용 여부',
                render: (row) => <Badge value={row.downloadAllowed ? '허용' : '차단'} />,
              },
              {
                key: 'actions',
                label: '열람',
                render: (row) => (
                  <span>
                    {row.previewAvailable === true && (
                      <button type="button" className="ghost" onClick={() => openPreview(row)}>
                        미리보기
                      </button>
                    )}
                    {row.downloadAllowed === true && (
                      <button type="button" className="ghost" onClick={() => openDownload(row)}>
                        다운로드
                      </button>
                    )}
                  </span>
                ),
              },
            ]}
            rows={rows}
            empty={loading ? '불러오는 중입니다.' : '이 문서에 등록된 첨부파일이 없습니다.'}
          />
          <Pager page={pageNo} size={PAGE_SIZE} total={data ? data.total : 0} onPage={setPageNo} />
        </div>
      )}
      {view && (
        <Drawer title={view.title} onClose={() => setView(null)}>
          <Pairs items={view.items} />
        </Drawer>
      )}
    </div>
  );
}
